(()=>{'use strict';let audio=null,speed=.8;try{const saved=Number(localStorage.getItem('hanzi-dialogue-speed'));if([.65,.8,1].includes(saved))speed=saved;}catch{}
function stop(){if(audio)audio.pause();audio=null;}
function mount(id){const card=document.querySelector('.reader-card'),source=window.HANZI_VOICE?.dialogues[id];if(!card||!source)return;card.querySelector('.room-dialogue-audio')?.remove();const host=document.createElement('div');host.className='room-dialogue-audio';host.innerHTML='<button type="button" data-dialogue-play>▶ Listen to dialogue</button><audio controls hidden aria-label="Mandarin dialogue recording"></audio><label class="audio-speed">Speed<select aria-label="Dialogue speed"><option value="0.65">Extra slow</option><option value="0.8">Slow</option><option value="1">Original</option></select></label>';const el=host.querySelector('audio');el.src=source;el.preload='metadata';el.playbackRate=speed;el.preservesPitch=true;if('webkitPreservesPitch'in el)el.webkitPreservesPitch=true;const select=host.querySelector('select');select.value=String(speed);select.onchange=()=>{speed=Number(select.value);el.playbackRate=speed;try{localStorage.setItem('hanzi-dialogue-speed',String(speed));}catch{}};card.querySelector('.card-top').after(host);el.onended=()=>host.querySelector('button').textContent='↺ Listen again';el.onpause=()=>{if(!el.ended)host.querySelector('button').textContent='▶ Continue dialogue';};}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-dialogue-play]');if(!b)return;const el=b.closest('.room-dialogue-audio').querySelector('audio');if(audio===el&&!el.paused){el.pause();return;}stop();audio=el;el.hidden=false;b.textContent='Loading recording…';try{await el.play();b.textContent='Ⅱ Pause dialogue';}catch{b.textContent='Use the player to listen';}});
window.HanziVoice={stop,mount};mount(document.querySelector('.reader-card')?.dataset.recording);document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
})();
